function scoreFromNorm(norms, sex, age, value) {
  const table = norms[sex === "female" ? "female" : "male"];
  const row = table.find((r) => age <= r.max) || table[table.length - 1];
  if (value >= row.e) return 5;
  if (value >= row.g) return 4;
  if (value >= row.a) return 3;
  if (value >= row.b) return 2;
  return 1;
}
function scoreFromBands(value, bands) {
  // bands: array descending [{min, score}] highest first
  for (const b of bands) if (value >= b.min) return b.score;
  return 1;
}
function scorePlank(sec) {
  return scoreFromBands(sec, [
    { min: 120, score: 5 }, { min: 90, score: 4 }, { min: 60, score: 3 },
    { min: 30, score: 2 }, { min: 0, score: 1 },
  ]);
}
function scoreSquat60(reps) {
  return scoreFromBands(reps, [
    { min: 45, score: 5 }, { min: 35, score: 4 }, { min: 25, score: 3 },
    { min: 15, score: 2 }, { min: 0, score: 1 },
  ]);
}
function scoreCardioMinutes(min) {
  return scoreFromBands(min, [
    { min: 30, score: 5 }, { min: 20, score: 4 }, { min: 12, score: 3 },
    { min: 5, score: 2 }, { min: 0, score: 1 },
  ]);
}
function scoreSitReach(cm) {
  return scoreFromBands(cm, [
    { min: 10, score: 5 }, { min: 0, score: 4 }, { min: -8, score: 3 },
    { min: -15, score: 2 }, { min: -999, score: 1 },
  ]);
}
