/* ============================================================================
   PROGRAM GENERATION
============================================================================ */
function pick(pool, idx) {
  return pool[idx % pool.length];
}

const PHASES = [
  { week: 1, phase: "Foundation", setsAdj: 0, repsAdj: 0, rpe: "5–6", note: "Groove technique and full range of motion before adding load or volume — this is the foundation the rest of the program builds on." },
  { week: 2, phase: "Foundation", setsAdj: 0, repsAdj: 1, rpe: "6", note: "Small rep increase while technique stays consistent. Consistency here predicts results later." },
  { week: 3, phase: "Build", setsAdj: 1, repsAdj: 1, rpe: "6–7", note: "Progressive overload: about a 5–10% bump in weekly training volume, the range shown to drive adaptation without overreaching." },
  { week: 4, phase: "Deload", setsAdj: -1, repsAdj: -2, rpe: "4–5", note: "Planned deload — volume drops roughly 40% so your body can absorb the last three weeks of training and come back stronger." },
  { week: 5, phase: "Build", setsAdj: 1, repsAdj: 1, rpe: "7", note: "Volume returns above the week-3 peak. This is where most visible strength and endurance gains start to show." },
  { week: 6, phase: "Build", setsAdj: 1, repsAdj: 2, rpe: "7–8", note: "Continued overload with a harder variation introduced where you scored strongest on your assessment." },
  { week: 7, phase: "Peak", setsAdj: 2, repsAdj: 2, rpe: "8", note: "Peak week — highest planned volume and intensity of the block, right before the taper." },
  { week: 8, phase: "Taper & Retest", setsAdj: -1, repsAdj: -2, rpe: "5–6", note: "Taper volume down so you're fresh to retake the movement screen and see your progress." },
];

function baseSetsReps(level, goal) {
  const sets = level === "Beginner" ? 2 : level === "Intermediate" ? 3 : 4;
  let reps = goal === "gain" ? 8 : goal === "lose" ? 12 : 10;
  return { sets, reps };
}

function generateProgram(a) {
  const equip = a.equipment; // none | home | gym
  const goal = a.goal;
  const levels = a.levels; // {endurance, strength, mobility}
  const daysPerWeek = a.daysPerWeek || 3;
  const weakest = Object.entries(levels).sort((x, y) => x[1].avg - y[1].avg)[0][0];

  const strengthLevel = levels.strength.label;
  const { sets: baseSets, reps: baseReps } = baseSetsReps(strengthLevel, goal);

  const dayTemplates3 = ["Full Body A", "Conditioning + Core", "Full Body B"];
  const dayTemplates4 = ["Lower + Core", "Upper + Conditioning", "Full Body", `Conditioning + Mobility (${weakest})`];
  const dayNames = daysPerWeek >= 4 ? dayTemplates4 : dayTemplates3;

  const weeks = PHASES.map((ph, wi) => {
    const sets = Math.max(2, baseSets + ph.setsAdj);
    const reps = Math.max(5, baseReps + ph.repsAdj);
    const days = dayNames.map((label, di) => {
      const idx = wi + di; // rotates exercise selection across weeks
      const warmup = [pick(EX.mobility, idx), pick(EX.mobility, idx + 3)];
      let main = [];
      let conditioning = null;
      let core = null;

      if (label.includes("Full Body") || label === "Lower + Core" || label === "Upper + Conditioning") {
        if (label !== "Upper + Conditioning") {
          main.push({ ex: pick(EX.squat[equip], idx), sets, reps, rest: "60–90s" });
          main.push({ ex: pick(EX.hinge[equip], idx), sets, reps, rest: "60–90s" });
        }
        if (label !== "Lower + Core") {
          main.push({ ex: pick(EX.push[equip], idx), sets, reps, rest: "60–75s" });
          main.push({ ex: pick(EX.pull[equip], idx), sets, reps, rest: "60–75s" });
        }
        core = [{ ex: pick(EX.core[equip], idx), sets: Math.max(2, sets - 1), reps: "30–45s or 10–12", rest: "45s" }];
      }
      if (label.includes("Conditioning")) {
        const roundsBase = levels.endurance.label === "Beginner" ? 4 : levels.endurance.label === "Intermediate" ? 6 : 8;
        conditioning = {
          ex: pick(EX.conditioning[equip], idx),
          format: `${Math.max(3, roundsBase + ph.setsAdj)} rounds — 30–40s work / 20–30s rest`,
        };
        core = core || [{ ex: pick(EX.core[equip], idx + 1), sets: Math.max(2, sets - 1), reps: "30–45s or 10–12", rest: "45s" }];
      }
      if (label.includes("Mobility")) {
        warmup.push(pick(EX.mobility, idx + 5), pick(EX.mobility, idx + 6));
      }
      return { label, warmup, main, conditioning, core };
    });
    return { ...ph, sets, reps, days };
  });

  return { generatedAt: Date.now(), equip, goal, daysPerWeek, weakest, weeks };
}

/* ============================================================================
   UNIT CONVERSION HELPERS (metric <> standard/imperial)
============================================================================ */
const CM_PER_IN = 2.54;
const KG_PER_LB = 0.453592;
function ftInToCm(ft, inch) { return Math.round(((+ft || 0) * 12 + (+inch || 0)) * CM_PER_IN); }
function cmToFtIn(cm) {
  const totalIn = (cm || 0) / CM_PER_IN;
  const ft = Math.floor(totalIn / 12);
  const inch = Math.round(totalIn - ft * 12);
  return { ft, inch };
}
function lbToKg(lb) { return Math.round((+lb || 0) * KG_PER_LB * 10) / 10; }
function kgToLb(kg) { return Math.round(((+kg || 0) / KG_PER_LB) * 10) / 10; }
function formatHeight(cm) {
  if (!cm) return "—";
  const { ft, inch } = cmToFtIn(cm);
  return `${ft}'${inch}" (${Math.round(cm)} cm)`;
}
function formatWeight(kg) {
  if (!kg && kg !== 0) return "—";
  return `${kgToLb(kg)} lb (${kg} kg)`;
}

/* ============================================================================
   NUTRITION CALCS
============================================================================ */
function calcNutrition(a) {
  const { sex, age, heightCm, weightKg, activity, goal } = a;
  const bmr = sex === "female"
    ? 10 * weightKg + 6.25 * heightCm - 5 * age - 161
    : 10 * weightKg + 6.25 * heightCm - 5 * age + 5;
  const tdee = bmr * (ACTIVITY_MULT[activity] || 1.375);
  const calories = Math.round(tdee * (1 + (GOAL_CAL_ADJUST[goal] || 0)));
  const proteinG = Math.round((GOAL_PROTEIN_PER_KG[goal] || 1.8) * weightKg);
  const fatCals = calories * (GOAL_FAT_PCT[goal] || 0.3);
  const fatG = Math.round(fatCals / 9);
  const proteinCals = proteinG * 4;
  const carbG = Math.max(0, Math.round((calories - proteinCals - fatCals) / 4));
  return { bmr: Math.round(bmr), tdee: Math.round(tdee), calories, proteinG, fatG, carbG };
}

