const TRAINER_EMAIL = "mendesmethod@gmail.com";
const BOOKING_WINDOW = { startHour: 6, endHour: 8 }; // 6:00 AM – 8:00 AM
const SLOT_MINUTES = 15;
const TIME_SLOTS = (() => {
  const out = [];
  for (let m = BOOKING_WINDOW.startHour * 60; m < BOOKING_WINDOW.endHour * 60; m += SLOT_MINUTES) {
    out.push(`${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`);
  }
  return out;
})();
function formatSlot12h(t) {
  const [h, m] = t.split(":").map(Number);
  const period = h < 12 ? "AM" : "PM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${pad2(m)} ${period}`;
}

/* ============================================================================
   .ICS CALENDAR FILE + GOOGLE CALENDAR QUICK-ADD HELPERS
   These generate a downloadable event or a pre-filled Google Calendar create
   link entirely in the browser — no OAuth/backend required. They invite
   ${TRAINER_EMAIL} as a guest rather than writing directly into that
   calendar (true two-way sync would need a server-side Google Calendar API
   connection, which this client-only app doesn't have).
============================================================================ */
function pad2(n) { return String(n).padStart(2, "0"); }
function icsStamp(dateStr, timeStr) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const [hh, mm] = (timeStr || "06:00").split(":").map(Number);
  return `${y}${pad2(m)}${pad2(d)}T${pad2(hh)}${pad2(mm)}00`;
}
function endTimeParts(dateStr, timeStr, durationMinutes) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const [hh, mm] = (timeStr || "06:00").split(":").map(Number);
  const end = new Date(y, m - 1, d, hh, mm + durationMinutes);
  return { dateStr: `${end.getFullYear()}-${pad2(end.getMonth() + 1)}-${pad2(end.getDate())}`, timeStr: `${pad2(end.getHours())}:${pad2(end.getMinutes())}` };
}
function downloadICS({ title, description, dateStr, timeStr, durationMinutes = 15 }) {
  if (!dateStr) return;
  const dtStart = icsStamp(dateStr, timeStr);
  const end = endTimeParts(dateStr, timeStr, durationMinutes);
  const dtEnd = icsStamp(end.dateStr, end.timeStr);
  const ics = [
    "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Mendes Method//Coaching Call//EN",
    "BEGIN:VEVENT",
    `UID:${Date.now()}@mendesmethod`,
    `DTSTAMP:${dtStart}`,
    `DTSTART:${dtStart}`,
    `DTEND:${dtEnd}`,
    `SUMMARY:${title}`,
    `DESCRIPTION:${(description || "").replace(/\n/g, "\\n")}`,
    `ATTENDEE:mailto:${TRAINER_EMAIL}`,
    "END:VEVENT", "END:VCALENDAR",
  ].join("\r\n");
  const blob = new Blob([ics], { type: "text/calendar" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = `${title.replace(/\s+/g, "-")}.ics`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
function googleCalendarLink({ title, description, dateStr, timeStr, durationMinutes = 15 }) {
  const dtStart = icsStamp(dateStr, timeStr);
  const end = endTimeParts(dateStr, timeStr, durationMinutes);
  const dtEnd = icsStamp(end.dateStr, end.timeStr);
  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: title,
    dates: `${dtStart}/${dtEnd}`,
    details: description || "",
    add: TRAINER_EMAIL,
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}
function nextWeekday(fromDateStr, targetDow) {
  const d = fromDateStr ? new Date(fromDateStr) : new Date();
  const diff = (targetDow - d.getDay() + 7) % 7 || 7;
  d.setDate(d.getDate() + diff);
  return d.toISOString().slice(0, 10);
}
function addDays(dateStr, days) {
  const d = new Date(dateStr);
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

