/* Signature element: Tri-Gauge — triangular radial gauge for Endurance / Strength / Mobility */
function TriGauge({ scores, size = 220, compareScores = null, labels = ["Endurance", "Strength", "Mobility"] }) {
  const cx = size / 2, cy = size / 2 - 6, R = size * 0.34;
  const angles = [-90, 30, 150].map((d) => (d * Math.PI) / 180);
  const pt = (r, ai) => [cx + r * Math.cos(angles[ai]), cy + r * Math.sin(angles[ai])];
  const poly = (vals) => vals.map((v, i) => pt((v / 5) * R, i).join(",")).join(" ");
  const ring = (frac) => angles.map((_, i) => pt(frac * R, i).join(",")).join(" ");
  return (
    <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
      {[0.33, 0.66, 1].map((f, i) => (
        <polygon key={i} points={ring(f)} fill="none" stroke="rgba(243,246,245,0.08)" strokeWidth="1" />
      ))}
      {angles.map((_, i) => {
        const [x, y] = pt(R, i);
        return <line key={i} x1={cx} y1={cy} x2={x} y2={y} stroke="rgba(243,246,245,0.08)" strokeWidth="1" />;
      })}
      {compareScores && (
        <polygon points={poly(compareScores)} fill="rgba(124,146,145,0.12)" stroke="rgba(124,146,145,0.5)" strokeWidth="1.5" strokeDasharray="4 3" />
      )}
      <polygon points={poly(scores)} fill="rgba(34,217,196,0.22)" stroke={COLORS.turquoise} strokeWidth="2.5" />
      {scores.map((v, i) => {
        const [x, y] = pt((v / 5) * R, i);
        return <circle key={i} cx={x} cy={y} r="4" fill={COLORS.turquoise} />;
      })}
      {labels.map((l, i) => {
        const [x, y] = pt(R + 26, i);
        return (
          <text key={l} x={x} y={y} fill={COLORS.paper} fontSize="12" fontWeight="700"
            textAnchor="middle" dominantBaseline="middle" fontFamily="Inter, sans-serif">{l}</text>
        );
      })}
    </svg>
  );
}

